package com.chondrimaishrat.elearning.lesson;
import com.chondrimaishrat.elearning.course.Course;
import com.chondrimaishrat.elearning.course.CourseRepository;
import com.chondrimaishrat.elearning.enrollment.EnrollmentRepository;
import com.chondrimaishrat.elearning.user.UserAccount;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;
@Service public class LessonService { private final LessonRepository lessons; private final CourseRepository courses; private final LessonCompletionRepository completions; private final EnrollmentRepository enrollments; public LessonService(LessonRepository l,CourseRepository c,LessonCompletionRepository x,EnrollmentRepository e){lessons=l;courses=c;completions=x;enrollments=e;} public List<Lesson> forCourse(Long id){return lessons.findByCourseIdOrderByPositionAsc(id);} @Transactional public void add(UserAccount instructor,Long courseId,LessonForm form){Course c=courses.findById(courseId).orElseThrow(()->new IllegalArgumentException("Course not found.")); if(!c.getInstructor().getId().equals(instructor.getId()))throw new IllegalArgumentException("You can only edit your own course."); lessons.save(new Lesson(c,form.getTitle().trim(),form.getContent().trim(),form.getVideoUrl(),form.getResourceUrl(),(int)lessons.countByCourseId(courseId)+1));} @Transactional public void complete(UserAccount student,Long lessonId){Lesson l=lessons.findById(lessonId).orElseThrow(()->new IllegalArgumentException("Lesson not found.")); if(!enrollments.existsByStudentIdAndCourseId(student.getId(),l.getCourse().getId()))throw new IllegalArgumentException("Enroll first."); if(!completions.existsByStudentIdAndLessonId(student.getId(),lessonId)) completions.save(new LessonCompletion(student,l));} public int progress(UserAccount student,Long courseId){long total=lessons.countByCourseId(courseId); return total==0?0:(int)(completions.countByStudentIdAndLessonCourseId(student.getId(),courseId)*100/total);} }
